      g.fillStyle = color; g.fill();
      px(g, 17, 12, 2, 14, lite); px(g, 12, 18, 12, 2, '#c9a04f');
    } else if (kind === 'light') {
      g.beginPath(); g.moveTo(18, 6); g.lineTo(27, 11); g.lineTo(24, 28); g.lineTo(18, 31); g.lineTo(12, 28); g.lineTo(9, 11); g.closePath();
