      g.fillStyle = color; g.beginPath(); g.arc(18, 18, 8, 0, Math.PI * 2); g.fill();
      g.fillStyle = shade(color, 0.5); g.beginPath(); g.arc(16, 16, 4, 0, Math.PI * 2); g.fill();
