13: function ell(g, cx, cy, rx, ry, color) {
14:   g.fillStyle = color;
15:   for (let y = -ry; y <= ry; y++) {
16:     const w = Math.round(rx * Math.sqrt(Math.max(0, 1 - (y * y) / (ry * ry))));
17:     g.fillRect(Math.round(cx - w), Math.round(cy + y), w * 2 + 1, 1);
18:   }
19: }
20: function R(g, x, y, w, h, c) { g.fillStyle = c; g.fillRect(Math.round(x), Math.round(y), Math.round(w), Math.round(h)); }
21: function line(g, x1, y1, x2, y2, col, w = 1) {
22:   g.fillStyle = col;
23:   const n = Math.max(Math.abs(x2 - x1), Math.abs(y2 - y1));
24:   for (let i = 0; i <= n; i++) {
25:     g.fillRect(Math.round(x1 + (x2 - x1) * i / n), Math.round(y1 + (y2 - y1) * i / n), w, w);
26:   }
27: }
