14: export const RARITY = Object.fromEntries(RARITIES.map((r) => [r.id, r]));
15: export const RARITY_RANK = Object.fromEntries(RARITIES.map((r) => [r.id, r.rank]));
16: export const RARITY_COLOR = Object.fromEntries(RARITIES.map((r) => [r.id, r.color]));
