171:   }
172:   map.props.push({kind:'well',x:308,y:170,sprite:0},{kind:'lamp',x:262,y:181,sprite:0},{kind:'lamp',x:354,y:181,sprite:1},
173:     {kind:'signpost',x:223,y:175,sprite:0},{kind:'portal',x:584,y:166,sprite:0},{kind:'elder',x:309,y:124,sprite:0});
