198:   drawables.push({y:p.y,draw:()=>{
199:     const image=frameForHero(); if(!image)return;
200:     ctx.fillStyle='rgba(0,0,0,.35)';ctx.beginPath();ctx.ellipse(p.x-cameraX,p.y-cameraY+11,11,4,0,0,Math.PI*2);ctx.fill();
201:     if(p.invuln>0&&Math.floor(elapsed*18)%2===0)ctx.globalAlpha=.45;
202:     ctx.drawImage(image,p.x-cameraX-24,p.y-cameraY-43,48,48);ctx.globalAlpha=1;
203:     if(p.attack>0){ctx.strokeStyle=state.path==='bow'?'#f4d179':'#cfeaff';ctx.lineWidth=3;ctx.beginPath();ctx.arc(p.x-cameraX+(p.dir===2?18:p.dir===3?-18:0),p.y-cameraY-10,25,-1.2,1.2);ctx.stroke();}
204:   }});
205:   drawables.sort((a,b)=>a.y-b.y).forEach(o=>o.draw());
206:   for(const z of state.zones){ctx.globalAlpha=.22+.08*Math.sin(elapsed*7);ctx.fillStyle=z.color;ctx.beginPath();ctx.arc(z.x-cameraX,z.y-cameraY,z.radius,0,Math.PI*2);ctx.fill();ctx.globalAlpha=.85;ctx.strokeStyle=z.color;ctx.lineWidth=2;ctx.stroke();ctx.globalAlpha=1;}
207:   for(const pr of state.projectiles){ctx.fillStyle=pr.color;ctx.shadowColor=pr.color;ctx.shadowBlur=10;ctx.beginPath();ctx.arc(pr.x-cameraX,pr.y-cameraY,pr.radius||6,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;}
208:   for(const item of state.loot){ctx.fillStyle=item.color||colors.gold;ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=9;ctx.fillRect(item.x-cameraX-4,item.y-cameraY-4,8,8);ctx.shadowBlur=0;}
209:   for(const fx of state.particles){ctx.globalAlpha=clamp(fx.life/fx.max,0,1);ctx.fillStyle=fx.color;ctx.fillRect(fx.x-cameraX,fx.y-cameraY,fx.size,fx.size);ctx.globalAlpha=1;}
