156: function makeWorld() {
157:   const rng = Math.random;
158:   map.tiles = Array.from({ length: map.height }, (_, y) => Array.from({ length: map.width }, (_, x) => {
159:     if (x < 2 || y < 2 || x > map.width - 3 || y > map.height - 3) return 2;
160:     if (Math.abs(y - (10 + Math.sin(x * .18) * 2)) < 1.2 && x > 3 && x < 36) return 3;
161:     return rng() < .18 ? 2 : 0;
162:   }));
163:   // A walkable road leads from the village to the eastern rift.
164:   for (let x = 4; x < 38; x++) for (let y = 9; y <= 11; y++) map.tiles[y][x] = 3;
165:   map.props = [];
166:   const propKinds = ['tree','pine','rock','bush','flower','mushroom','stump','grave','crystal'];
167:   for (let i=0;i<60;i++) {
168:     const x = rand(48, W-48), y = rand(48, H-45);
169:     if ((x < 200 && y < 190) || (x > 545 && y > 115 && y < 220)) continue;
170:     map.props.push({ kind: pick(propKinds), x, y, sprite: randInt(0, (art.props[pick(propKinds)]||[{}]).length-1) });
171:   }
172:   map.props.push({kind:'well',x:308,y:170,sprite:0},{kind:'lamp',x:262,y:181,sprite:0},{kind:'lamp',x:354,y:181,sprite:1},
173:     {kind:'signpost',x:223,y:175,sprite:0},{kind:'portal',x:584,y:166,sprite:0},{kind:'elder',x:309,y:124,sprite:0});
174: }
175: function spriteForProp(p) { return p.kind==='elder' ? art.npcs.elder?.down?.[0] : art.props[p.kind]?.[p.sprite % (art.props[p.kind]?.length||1)]; }
176: function frameForHero() {
177:   const p = state.player; const dir = p.dir===0?'down':p.dir===1?'up':p.dir===2?'side':'side';
178:   const list = heroSprites?.[dir] || heroSprites?.down;
179:   return list?.[Math.floor(p.frame/8)%list.length];
180: }
181: function drawWorld() {
182:   ctx.clearRect(0,0,W,H);
183:   const p=state.player, cameraX=clamp(p.x-W/2,0,map.width*tileSize-W), cameraY=clamp(p.y-H/2,0,map.height*tileSize-H);
184:   const x0=Math.floor(cameraX/tileSize),y0=Math.floor(cameraY/tileSize);
185:   for(let y=y0;y<=y0+Math.ceil(H/tileSize);y++) for(let x=x0;x<=x0+Math.ceil(W/tileSize);x++) {
186:     const id=map.tiles[y]?.[x]??2, variants=art.tiles[id]||art.tiles[0];
187:     const tile=Array.isArray(variants[0])?variants[0][Math.floor((elapsed*2+x+y)%variants[0].length)]:variants[(x*17+y*31)%variants.length];
188:     ctx.drawImage(tile,x*tileSize-cameraX,y*tileSize-cameraY);
189:   }
190:   const drawables=[];
191:   for(const prop of map.props) drawables.push({y:prop.y+20,draw:()=>{
192:     const img=spriteForProp(prop); if(!img)return;
193:     const w=prop.kind==='elder'?40:prop.kind==='portal'?54:img.width*2,h=prop.kind==='elder'?54:prop.kind==='portal'?56:img.height*2;
194:     ctx.drawImage(img,prop.x-cameraX-w/2,prop.y-cameraY-h+18,w,h);
195:     if(prop.kind==='portal'){ctx.globalAlpha=.23+.12*Math.sin(elapsed*3);ctx.fillStyle='#9a6cff';ctx.beginPath();ctx.ellipse(prop.x-cameraX,prop.y-cameraY-18,24,34,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;}
196:   }});
197:   for(const e of state.enemies) drawables.push({y:e.y,draw:()=>drawEnemy(e,cameraX,cameraY)});
198:   drawables.push({y:p.y,draw:()=>{
199:     const image=frameForHero(); if(!image)return;
200:     ctx.fillStyle='rgba(0,0,0,.35)';ctx.beginPath();ctx.ellipse(p.x-cameraX,p.y-cameraY+11,11,4,0,0,Math.PI*2);ctx.fill();
201:     if(p.invuln>0&&Math.floor(elapsed*18)%2===0)ctx.globalAlpha=.45;
202:     ctx.drawImage(image,p.x-cameraX-24,p.y-cameraY-43,48,48);ctx.globalAlpha=1;
203:     if(p.attack>0){ctx.strokeStyle=state.path==='bow'?'#f4d179':'#cfeaff';ctx.lineWidth=3;ctx.beginPath();ctx.arc(p.x-cameraX+(p.dir===2?18:p.dir===3?-18:0),p.y-cameraY-10,25,-1.2,1.2);ctx.stroke();}
204:   }});
205:   drawables.sort((a,b)=>a.y-b.y).forEach(o=>o.draw());
206:   for(const z of state.zones){ctx.globalAlpha=.22+.08*Math.sin(elapsed*7);ctx.fillStyle=z.color;ctx.beginPath();ctx.arc(z.x-cameraX,z.y-cameraY,z.radius,0,Math.PI*2);ctx.fill();ctx.globalAlpha=.85;ctx.strokeStyle=z.color;ctx.lineWidth=2;ctx.stroke();ctx.globalAlpha=1;}
207:   for(const pr of state.projectiles){ctx.fillStyle=pr.color;ctx.shadowColor=pr.color;ctx.shadowBlur=10;ctx.beginPath();ctx.arc(pr.x-cameraX,pr.y-cameraY,pr.radius||6,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;}
208:   for(const item of state.loot){ctx.fillStyle=item.color||colors.gold;ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=9;ctx.fillRect(item.x-cameraX-4,item.y-cameraY-4,8,8);ctx.shadowBlur=0;}
209:   for(const fx of state.particles){ctx.globalAlpha=clamp(fx.life/fx.max,0,1);ctx.fillStyle=fx.color;ctx.fillRect(fx.x-cameraX,fx.y-cameraY,fx.size,fx.size);ctx.globalAlpha=1;}
210:   // Night tint and local light pools retain the pixel-art contrast.
211:   const night=.22+.25*(.5+.5*Math.sin(elapsed*.035));ctx.fillStyle=`rgba(5,9,25,${night})`;ctx.fillRect(0,0,W,H);
212:   const light=ctx.createRadialGradient(p.x-cameraX,p.y-cameraY,22,p.x-cameraX,p.y-cameraY,175);light.addColorStop(0,'rgba(255,221,157,.17)');light.addColorStop(1,'rgba(0,0,0,.35)');ctx.fillStyle=light;ctx.fillRect(0,0,W,H);
213:   if(state.weather==='ASHFALL'){ctx.fillStyle='rgba(210,190,180,.45)';for(let i=0;i<45;i++){const x=(i*83+elapsed*28)%W,y=(i*47+elapsed*51)%H;ctx.fillRect(x,y,1,2);}}
214:   drawMinimap();
215: }
