230: function addParticles(x,y,color,count=10){for(let i=0;i<count;i++){const a=rand(0,Math.PI*2),speed=rand(18,100);state.particles.push({x,y,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,life:rand(.2,.7),max:.7,color,size:randInt(1,3)});}}
231: function nearestEnemy(range=90){return state.enemies.filter(e=>dist(state.player,e)<range).sort((a,b)=>dist(state.player,a)-dist(state.player,b))[0];}
232: function damageEnemy(e,damage,color='#fff'){
233:   if(!state.enemies.includes(e))return;
234:   const mods=state.ability?.passive?.mods||{}; damage*=1+(mods.atkPct||0);
235:   damage*=state.equipment.weapon?.mult||1; e.hp-=damage;e.hit=.12;addParticles(e.x,e.y-12,color,5);
236:   if(mods.lifesteal)state.hp=Math.min(state.maxHp,state.hp+damage*mods.lifesteal);
237:   if(e.hp<=0)killEnemy(e);
238: }
239: function killEnemy(e){
240:   state.enemies=state.enemies.filter(v=>v!==e);state.kills++;state.combo=(state.combo||0)+1;gainXp(e.boss?180:22);
241:   state.gold+=e.boss?120:randInt(3,10);if(Math.random()<.35)state.loot.push({x:e.x,y:e.y,color:'#e7c26b',kind:'gold',amount:randInt(5,18)});
242:   if(Math.random()<.12)state.loot.push({x:e.x+8,y:e.y,color:'#71daff',kind:'potion'});
243:   if(state.ability?.passive?.mods?.manaOnKill)state.mp=Math.min(state.maxMp,state.mp+state.ability.passive.mods.manaOnKill);
244:   addParticles(e.x,e.y,'#ffb56b',18);if(e.boss){state.bossDefeated=true;state.dungeon=false;state.zone='HOLLOWMERE';state.player.x=320;state.player.y=205;setQuest('The Last Awakened','The Rift Warden is defeated. Hollowmere is safe—for now.');showToast('RIFT WARDEN DEFEATED · DUNGEON CLEARED',colors.gold);}
245:   updateHud();saveGame();
246: }
247: function attack(heavy=false){
248:   if(state.mode!=='world'||state.player.attack>0)return;
249:   const p=state.player,weapon=state.path;p.attack=heavy?.42:.25;state.player.frame+=1;
250:   const range=weapon==='bow'?155:weapon==='staff'?100:66, target=nearestEnemy(range);
