34: export function rollItemRarity(rng = Math.random, luck = 0, floorRank = 0) {
35:   const weights = RARITIES.map((r) => ({
36:     value: r.id,
37:     weight: Math.max(0.02, r.itemWeight * (1 + (r.rank > 1 ? luck * 0.12 : 0))),
38:   }));
39:   let total = 0;
40:   for (const w of weights) {
41:     if (RARITY[w.value].rank >= floorRank) total += w.weight;
42:   }
43:   let roll = rng() * total;
44:   for (const w of weights) {
45:     if (RARITY[w.value].rank < floorRank) continue;
46:     roll -= w.weight;
47:     if (roll <= 0) return w.value;
48:   }
49:   return 'common';
50: }

