function rollAbility(){const rarity=weightedPick(AWAKENING_WEIGHTS),pool=[...abilities,...ascendant].filter(a=>a.rarity===rarity);return pick(pool)||pick(abilities);}
function makeMap(dungeon=false){
  map.width=dungeon?20:40;map.height=dungeon?12:28;map.tiles=[];map.props=[];
  for(let y=0;y<map.height;y++){map.tiles[y]=[];for(let x=0;x<map.width;x++){
    const nearPath=!dungeon&&(Math.abs(y-13)<2||Math.abs(x-10)<2||Math.abs(y-13-(x-10)*.45)<1.2);
    const edge=x===0||y===0||x===map.width-1||y===map.height-1;
    let t=dungeon?(edge?9:(Math.random()<.05?13:8)):(edge?2:(nearPath?3:(Math.random()<.22?1:0)));
    if(!dungeon&&!edge&&x>22&&Math.random()<.1)t=4;
    map.tiles[y][x]=t;
  }}
  map.worldW=map.width*tileSize;map.worldH=map.height*tileSize;
  if(dungeon){
    map.props=[{type:'crystal',x:170,y:115},{type:'torch',x:468,y:116},{type:'pillar',x:142,y:285},{type:'pillar',x:500,y:285},{type:'chest',x:530,y:170,interact:'chest'}];
  }else{
    map.props=[{type:'house',x:145,y:155},{type:'smithy',x:455,y:135},{type:'well',x:280,y:315},{type:'lamp',x:280,y:175},{type:'lamp',x:380,y:175},{type:'tree',x:82,y:250},{type:'tree',x:530,y:250},{type:'tree',x:650,y:160},{type:'tree',x:740,y:350},{type:'pine',x:890,y:180},{type:'deadTree',x:1000,y:300},{type:'rock',x:930,y:470},{type:'rift',x:1170,y:430,interact:'rift'},{type:'portal',x:1170,y:430}];
    if(art.npcs?.elder)map.props.push({type:'npc',look:'elder',x:350,y:220,interact:'elder',name:'Elder Orin'});
    map.props.push({type:'npc',look:'smith',x:475,y:205,interact:'smith',name:'Blacksmith'});
  }
}
function beginCharacter(){
  state.name=$('#char-name').value.trim().slice(0,16)||'Wanderer';state.player.x=320;state.player.y=250;state.player.dir=0;state.hp=state.maxHp=100;state.mp=state.maxMp=60;state.stamina=100;state.level=1;state.xp=0;state.xpNext=100;state.gold=35;state.kills=0;state.quest=0;state.dungeon=false;state.bossDefeated=false;state.ability=rollAbility();state.enemies=[];state.inventory=[];state.equipment={weapon:null,armor:null};state.potions=3;state.manaPotions=2;state.cooldowns=[0,0,0];state.dungeonStage=0;state.buffs={};state.mode='awakening';makeMap(false);hideScreens();$('#hud').classList.remove('hidden');$('#touch-controls').classList.remove('hidden');$('#awakening-screen').classList.remove('hidden');$('#awaken-name').textContent=state.name;populateAwakening();updateHud();saveGame();
}
function populateAwakening(){const a=state.ability,r=rarityOf(a.rarity);$('#reveal-rarity').textContent=r.name.toUpperCase();$('#reveal-rarity').style.color=r.color;$('#reveal-sigil').textContent=a.sigil;$('#reveal-sigil').style.color=a.color;$('#reveal-name').textContent=a.name;$('#reveal-name').style.color=r.color;$('#reveal-desc').textContent=a.desc;$('#reveal-passive').innerHTML=`<b>INNATE PASSIVE</b><span>${a.passive.text}</span>`;$('#reveal-stats').innerHTML=`<span>ATTACK <b>+${Math.round((a.passive.mods.atkPct||0)*100)}%</b></span><span>DEFENSE <b>+${Math.round((a.passive.mods.defPct||0)*100)}%</b></span><span>EVOLUTION <b>LV 5 / 10</b></span>`;$('#reveal-skills').innerHTML=a.skills.map((s,i)=>`<div><kbd>${['Q','E','R'][i]}</kbd><b>${s.name}</b><small>${s.desc}</small></div>`).join('');$('#ability-reveal').style.setProperty('--rarity-color',r.color);}
const lines=[['Elder Orin','The sky has been gone for seven years. Tonight, the old stones are answering again.'],['Elder Orin','You came back from the northern road alive. That is more than most can say. The System chose you.'],['Elder Orin','When the bells ring, the village sleeps behind its ward. Find the rift beyond the eastern watchtower. Do not go alone.']];
function openDialogue(){dialogueIndex=0;$('#dialogue-layer').classList.remove('hidden');$('#dialogue-choices').innerHTML='';if(art.npcPortraits.elder)$('#dialogue-portrait').getContext('2d').drawImage(art.npcPortraits.elder,0,0,64,72);renderDialogue();}
function renderDialogue(){const [speaker,text]=lines[Math.min(dialogueIndex,lines.length-1)];$('#dialogue-speaker').textContent=speaker;$('#dialogue-text').textContent=text;$('#dialogue-choices').innerHTML=dialogueIndex>=lines.length-1?'<button data-choice="rift">I will find the rift. <span>→</span></button><button data-choice="later">I need a moment.</button>':'';}
function closeDialogue(choice){$('#dialogue-layer').classList.add('hidden');if(choice==='rift'){state.quest=1;showToast('QUEST UPDATED · The Shattered Threshold');setQuest('The Shattered Threshold','Travel east and enter the rift.');saveGame();}if(choice==='later')showToast('Orin waits by the old well.');}
function setQuest(name,objective){$('#quest-name').textContent=name;$('#quest-objective').textContent=objective;}
function acceptAwakening(){$('#awakening-screen').classList.add('hidden');state.mode='world';setQuest('A System Awakens','Speak with Elder Orin in Hollowmere.');showToast(`${rarityOf(state.ability.rarity).name.toUpperCase()} AUTHORITY ACQUIRED`,rarityOf(state.ability.rarity).color);spawnAmbientEnemies();saveGame();}
function spawnAmbientEnemies(){const types=Object.keys(art.monsters||{});for(let i=0;i<5;i++)spawnEnemy(pick(types),rand(590,1030),rand(100,700),false);}
function spawnEnemy(type,x,y,boss=false){state.enemies.push({type:type||'wraith',x,y,hp:boss?540:30+state.level*7,maxHp:boss?540:30+state.level*7,speed:boss?32:rand(22,34),damage:boss?18:8+state.level,attackCd:rand(.4,1.8),frame:0,hit:0,boss,stun:0,slow:0,attack:0});}

