499:     const a = t * TAU * 1.5;
500:     const rr = 2 + t * 9;
501:     const x = 28 + Math.cos(a) * rr, y = 44 + Math.sin(a) * rr * 1.3;
502:     i ? g.lineTo(x, y) : g.moveTo(x, y);
503:   }
