560:   g.fillStyle = '#d4ac58'; g.fillRect(92, 89, 2, 2);
561:   g.fillStyle = '#2a1b11'; g.fillRect(75, 72, 26, 3);
562:   // windows
563:   const win = (x, y) => {
564:     g.fillStyle = '#2b1e13'; g.fillRect(x, y, 19, 17);
565:     g.fillStyle = '#e3b75e'; g.fillRect(x + 2, y + 2, 15, 13);
