111: export function shade(hex, amt) {
112:   const h = hex.replace('#', '');
113:   const num = parseInt(h.length === 3 ? h.split('').map((c) => c + c).join('') : h, 16);
114:   let r = (num >> 16) & 255, g = (num >> 8) & 255, b = num & 255;
115:   if (amt >= 0) {
116:     r += (255 - r) * amt; g += (255 - g) * amt; b += (255 - b) * amt;
117:   } else {
118:     r *= 1 + amt; g *= 1 + amt; b *= 1 + amt;
119:   }
120:   return `rgb(${Math.round(r)},${Math.round(g)},${Math.round(b)})`;
121: }
