import { art, initArt, buildHeroSprites, drawPreview, makePortrait } from './art/index.js';
import { LOW_ABILITIES } from './data/abilities/low.js';
import { MID_ABILITIES } from './data/abilities/mid.js';
import { RARITIES } from './data/rarity.js';
import { clamp, dist, pick, weightedPick, rand, randInt, hash2 } from './utils.js';

const $ = (s) => document.querySelector(s);
const $$ = (s) => [...document.querySelectorAll(s)];
const canvas = $('#game'), ctx = canvas.getContext('2d');
ctx.imageSmoothingEnabled = false;
const W = canvas.width, H = canvas.height, TS = 32;
const data = { name:'', hair:0, hairColor:'#2b2533', cloakColor:'#25324d', path:'sword' };
const names = ['Ash','Mira','Rowan','Kael','Vesper','Sable','Iris','Riven'];
const rarePool = [...LOW_ABILITIES, ...MID_ABILITIES];
const highModels = [
  { id:'sun', name:'Solar Dominion', sigil:'☼', color:'#ffd36a', tagline:'A star has mistaken your heart for a horizon.', desc:'You command the merciless radiance that once forged the first dawn.', passive:{text:'+25% Attack. Your strikes sear nearby foes.',mods:{atkPct:.25,burn:.3}}, skills:[{name:'Sun Lance',kind:'projectile',mana:18,cd:3,dmg:3.5,speed:430,radius:14,color:'#ffe477'},{name:'Corona',kind:'nova',mana:24,cd:9,dmg:2.8,radius:130,color:'#ffb52e'},{name:'Daybreak',kind:'buff',mana:30,cd:24,duration:9,mods:{atkPct:.5,movePct:.2},color:'#fff2a3'}] },
  { id:'void', name:'Void Sovereignty', sigil:'◉', color:'#ba8bff', tagline:'There is no bottom to the dark that answers you.', desc:'The space between stars bends around your will.', passive:{text:'+18% Attack and +12% Dodge. Your presence weakens nearby foes.',mods:{atkPct:.18,dodge:.12}}, skills:[{name:'Abyssal Bolt',kind:'projectile',mana:18,cd:3.5,dmg:3.2,speed:400,radius:13,color:'#bb85ff'},{name:'Eventide',kind:'pull',mana:26,cd:11,dmg:1.2,radius:125,duration:3,color:'#7b54cf'},{name:'Nullstep',kind:'dash',mana:22,cd:8,dmg:3,distance:220,radius:52,color:'#d0b4ff'}] },
  { id:'storm', name:'Worldstorm', sigil:'ϟ', color:'#93eaff', tagline:'The first thunder was only your name arriving.', desc:'The weather itself has become an extension of your nervous system.', passive:{text:'+20% Attack speed and +18% critical chance.',mods:{atkPct:.18,atkSpeed:.2,crit:.18}}, skills:[{name:'Skyfire',kind:'chain',mana:20,cd:4,dmg:3,range:260,count:7,color:'#b0edff'},{name:'Tempest Ring',kind:'nova',mana:26,cd:9,dmg:2.8,radius:120,color:'#6ddcff'},{name:'Stormskin',kind:'buff',mana:28,cd:20,duration:8,mods:{movePct:.35,atkPct:.3},color:'#b0edff'}] }
];
function makeHighAbility(rarity) {
  const base = structuredClone(pick(highModels));
  const level = RARITIES.findIndex(r=>r.id===rarity);
  const scale = [1,1.18,1.42,1.75,2.2,2.8,3.6][level] || 2.2;
  base.id += `-${rarity}`; base.rarity=rarity; base.name = `${base.name} ${rarity==='divine'?'Transcendent':'Ascendant'}`;
  base.evolution=[{level:5,name:'Sovereign Aspect',desc:'Authority deepens: +12% damage and wider skill effects.',mods:{atkPct:.12,radiusPct:.12}},{level:10,name:'Unbounded Authority',desc:'The System recognizes no ceiling.',mods:{atkPct:.18,cdr:.1}}];
  base.skills=base.skills.map(s=>({...s,dmg:(s.dmg||0)*scale,mana:Math.round(s.mana*1.1),radius:s.radius?Math.round(s.radius*(1+(scale-1)*.15)):undefined}));
  base.passive={...base.passive,mods:{...base.passive.mods,atkPct:(base.passive.mods.atkPct||0)+(scale-1)*.1}};
  return base;
}
function rollAbility(){
  const rarity=weightedPick(RARITIES.map(r=>({value:r.id,weight:r.weight})));
  const candidates=rarePool.filter(a=>a.rarity===rarity);
  const ability=candidates.length?pick(candidates):makeHighAbility(rarity);
  if(candidates.length) ability.rarity=rarity;
  return ability;
}
let heroSprites, heroPortrait, player, monsters=[], projectiles=[], effects=[], drops=[], props=[], mapType='village', mapSeed=1, mapW=52, mapH=38, camera={x:0,y:0}, time=0,last=0, keys={}, mouse={x:W/2,y:H/2,down:false}, touchMove={x:0,y:0}, modalTab='status', dialogueQueue=[], toastTimer=0, saveTimer=0, comboTimer=0, lastAttack=0, paused=false;
const monsterTypes=['slime','wolf','bandit','skeleton','wraith','golem','spider','knight','dragonling','cultist','boar'];
const mapZones=[{name:'Hollowmere',type:'village',tile:0,weather:'CLEAR'},{name:'Whispering Wood',type:'forest',tile:2,weather:'MIST'},{name:'Sunken Reliquary',type:'dungeon',tile:8,weather:'DUST'},{name:'Ashen Caldera',type:'lava',tile:12,weather:'ASH'}];
function show(id,yes=true){$(id)?.classList.toggle('hidden',!yes)}
function toast(msg){const el=document.createElement('div');el.className='toast';el.textContent=msg;$('#toast-layer').append(el);setTimeout(()=>el.remove(),2800)}
function setTitle(){show('#title-screen');show('#creation-screen',false);show('#hud',false);show('#touch-controls',false);show('#dialogue-layer',false);show('#awakening-screen',false);show('#system-overlay',false)}
function randomName(){return pick(names)+['',' the Unbound',' Vale',' Ashborn'][randInt(0,3)]}
function updatePreview(){data.name=$('#char-name').value.trim()||'Unnamed';$('#preview-name').textContent=data.name.toUpperCase();$('#preview-path').textContent=`PATH OF THE ${data.path.toUpperCase()}`;drawPreview($('#preview-canvas'),data,time)}
function updatePortraits(){if(!heroSprites)return;heroSprites=buildHeroSprites(data);heroPortrait=makePortrait(heroSprites.down[0],48,56,2.1,0);$('#hud-portrait').getContext('2d').drawImage(heroPortrait,0,0);$('#sys-portrait').getContext('2d').drawImage(makePortrait(heroSprites.down[0],40,46,1.8,0),0,0)}
function createPlayer(ability){
  const pathStats={sword:{atk:15,range:48,speed:1},bow:{atk:12,range:230,speed:1.1},staff:{atk:13,range:150,speed:1.05}}[data.path];
  player={x:W/2,y:H/2,hp:120,maxHp:120,mp:70,maxMp:70,stamina:100,level:1,xp:0,nextXp:100,gold:25,atk:pathStats.atk,range:pathStats.range,weaponSpeed:pathStats.speed,dir:0,anim:0,frame:0,attack:0,dodge:0,invuln:0,shield:0,mods:{},buffs:[],ability,cd:[0,0,0],potions:3,elixirs:2,kills:0,quests:0,inventory:[],equipment:[],bossKills:0,playTime:0};
  applyMods(ability.passive?.mods||{}); ability.evolution?.forEach(e=>{if(player.level>=e.level)applyMods(e.mods)});
  if(data.path==='bow')player.atk-=1;
  player.xp=0; monsters=[];projectiles=[];effects=[];drops=[];
  createMap('village'); updatePortraits();updateHUD();
}
function applyMods(m){for(const [k,v] of Object.entries(m||{})){if(typeof v==='number')player.mods[k]=(player.mods[k]||0)+v}}
function createMap(type,depth=1){
  const zone=mapZones.find(z=>z.type===type)||mapZones[0];mapType=type;mapSeed=randInt(0,999999);mapW=type==='village'?44:58;mapH=type==='village'?34:48;
  player.x=mapW*TS/2;player.y=mapH*TS/2; monsters=[];projectiles=[];effects=[];drops=[];props=[];
  for(let i=0;i<45;i++){const x=rand(2,mapW-2)*TS,y=rand(2,mapH-2)*TS; if(dist(x,y,player.x,player.y)>160)props.push({x,y,type:pick(['tree','rock','ruin']),seed:randInt(0,9)})}
  if(type==='village'){
    props.push({x:player.x+80,y:player.y-15,type:'elder',npc:true});props.push({x:player.x-170,y:player.y+35,type:'merchant',npc:true});
    $('#quest-name').textContent='A System Awakens';$('#quest-objective').textContent='Speak with Elder Orin in Hollowmere.';
  } else {
    const count=10+depth*2; for(let i=0;i<count;i++)spawnMonster(false,depth);
    props.push({x:player.x+250,y:player.y,type:'gate',npc:true});
    $('#quest-name').textContent=type==='dungeon'?`Reliquary Depth ${depth}`:'Purge the Blight';$('#quest-objective').textContent=`Defeat ${Math.max(1,count)} creatures and find the return gate.`;
  }
  $('#hud-zone').textContent=zone.name.toUpperCase();$('#mini-label').textContent=zone.name.toUpperCase();$('#hud-weather').textContent=zone.weather;
  player.zone=zone.name;player.depth=depth; updateHUD();
}
function spawnMonster(boss=false,depth=player.depth||1){
 const type=boss?pick(['boss_grove','boss_wyrm','boss_hollow']):pick(monsterTypes);
 const hp=(boss?480:40+player.level*11+depth*8)*(boss?1:rand(.8,1.25));
 monsters.push({x:rand(90,mapW*TS-90),y:rand(90,mapH*TS-90),type,hp,maxHp:hp,atk:boss?20:7+depth*2,speed:boss?48:rand(35,62),radius:boss?25:12,dir:0,anim:rand(0,5),attackCd:rand(.2,2),boss,stun:0,slow:0,burn:0,aggro:false,loot:boss?randInt(55,100):randInt(4,15),color:boss?'#ff526c':'#d94f5e'});
}

