monsters.push({x,y,type,hp,maxHp:hp,atk:boss?20:7+d*2,speed:boss?48:rand(35,62),radius:boss?25:12,dir:0,anim:rand(0,5),attackCd:rand(.2,2),boss,stun:0,slow:0,burn:0,aggro:false,loot:boss?randInt(55,100):randInt(4,15),color:boss?'#ff526c':'#d94f5e'})}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function rarity(id){return RARITIES.find(r=>r.id===id)||RARITIES[0]}
function beginAwakening(){player=createPlayer(rollAbility());$('#awaken-name').textContent=data.name;const a=player.ability,r=rarity(a.rarity);$('#reveal-rarity').textContent=r.name.toUpperCase();$('#reveal-rarity').style.color=r.color;$('#reveal-sigil').textContent=a.sigil||'✦';$('#reveal-sigil').style.color=a.color||r.color;$('#reveal-name').textContent=a.name;$('#reveal-desc').textContent=a.desc;$('#reveal-passive').innerHTML=`<b>PASSIVE AUTHORITY</b><p>${escapeHTML(a.passive?.text||'A dormant power stirs.')}</p>`;$('#reveal-stats').innerHTML=`<span>${r.name} authority</span><span>${data.path.toUpperCase()} path</span>`;$('#reveal-skills').innerHTML=(a.skills||[]).map((s,i)=>`<div><b>${['Q','E','R'][i]} · ${escapeHTML(s.name)}</b><small>${escapeHTML(s.desc||`${s.kind} · ${s.mana} MP`)}</small></div>`).join('');show('#creation-screen',false);show('#awakening-screen');updateSkillBar()}
function enterWorld(){show('#awakening-screen',false);show('#title-screen',false);show('#hud');show('#touch-controls',matchMedia('(pointer:coarse)').matches);paused=false;updateHUD();renderSystem('status');saveGame();toast('The System has marked you. Speak with Elder Orin.');requestAnimationFrame(loop)}
function startDialogue(npc){selectedNpc=npc;paused=true;show('#dialogue-layer');$('#dialogue-speaker').textContent=npc==='merchant'?'Mara the Merchant':'Elder Orin';const text=npc==='merchant'?'The road is hungry. I can spare a field tonic if you can spare ten gold.':dialogueDone?'The rift stirs beyond the village. Take the old road east, and do not look back.':'The eclipse took the sun, but not all its light. An old power has found you. Accept the System, Awakened.';$('#dialogue-text').textContent=text;$('#dialogue-choices').innerHTML=npc==='merchant'?'<button data-action="buy-potion">Buy tonic · 10 gold</button><button data-action="close-dialogue">Leave</button>':'<button data-action="accept">Accept the awakening</button><button data-action="close-dialogue">Not yet</button>';}
function closeDialogue(){show('#dialogue-layer',false);paused=false;selectedNpc=null;if(!dialogueDone&&player){$('#quest-objective').textContent='Return to Elder Orin after accepting your awakening.'}}
function updateSkillBar(){if(!player)return;player.ability.skills.forEach((s,i)=>{$(`#sname-${i}`).textContent=s.name; $(`#icon-${i}`).textContent=(player.ability.sigil||'✦');$(`#slot-${i}`).style.setProperty('--skill-color',s.color||player.ability.color||'#8bd4ff')})}
function updateHUD(){if(!player)return;$('#hud-name').textContent=data.name;$('#hud-title').textContent=player.ability.name;$('#hud-level').textContent=player.level;$('#bar-hp').style.width=`${100*player.hp/player.maxHp}%`;$('#bar-mp').style.width=`${100*player.mp/player.maxMp}%`;$('#bar-sp').style.width=`${player.stamina}%`;$('#bar-xp').style.width=`${100*player.xp/player.nextXp}%`;$('#txt-hp').textContent=`${Math.ceil(player.hp)} / ${player.maxHp}`;$('#txt-mp').textContent=`${Math.ceil(player.mp)} / ${player.maxMp}`;$('#txt-sp').textContent=`${Math.ceil(player.stamina)}`;$('#txt-xp').textContent=`${player.xp} / ${player.nextXp} XP`;$('#hud-gold').textContent=player.gold;$('#potion-count').textContent=player.potions;$('#mana-count').textContent=player.elixirs;$('#combo-count').textContent=player.combo||0;$('#combo-meter').classList.toggle('active',(player.combo||0)>1);$('#sys-mini-name').textContent=data.name;$('#sys-mini-level').textContent=`LV ${player.level} · AWAKENED`;$('#sys-gold').textContent=`◉ ${player.gold}`;$('#hud-time').textContent=`${String(21+Math.floor(time/90)%3).padStart(2,'0')}:${String(Math.floor(time*2)%60).padStart(2,'0')}`;$('#hud-day').textContent=`DAY ${1+Math.floor(time/180)}`;$('#sys-clock').textContent=`${$('#hud-time').textContent} · ${player.zone.toUpperCase()}`;updateSkillBar()}
function saveGame(){if(!player)return;try{localStorage.setItem(SAVE_KEY,JSON.stringify({data,player,mapType,depth,dialogueDone}))}catch(e){console.warn('Could not save game',e)}}
