function renderSystem(tab){if(!player)return;modalTab=tab;$$('#sys-tabs [data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));const title=tab.toUpperCase();$('#sys-title').textContent=title;$('#sys-kicker').textContent=`SYSTEM / ${title}`;const c=$('#sys-content'),a=player.ability,r=rarity(a.rarity);let html='';
 if(tab==='status')html=`<div class="status-grid"><section class="sys-card"><h3>SOUL PROFILE</h3><div class="stat-line"><span>Level</span><b>${player.level}</b></div><div class="stat-line"><span>Path</span><b>${data.path.toUpperCase()}</b></div><div class="stat-line"><span>Attack</span><b>${Math.round(player.atk*(1+(player.mods.atkPct||0)))}</b></div><div class="stat-line"><span>Critical</span><b>${Math.round((player.mods.crit||0)*100)}%</b></div><div class="stat-line"><span>Enemies defeated</span><b>${player.kills}</b></div><div class="stat-line"><span>Bosses defeated</span><b>${player.bossKills}</b></div></section><section class="sys-card ability-card" style="--rarity:${r.color}"><h3>${escapeHTML(a.name)}</h3><small>${r.name.toUpperCase()} · ${escapeHTML(a.tagline||'Awakened authority')}</small><p>${escapeHTML(a.desc)}</p><b>PASSIVE</b><p>${escapeHTML(a.passive?.text||'')}</p></section><section class="sys-card"><h3>ATTRIBUTES</h3><div class="stat-line"><span>Vitality</span><b>${Math.round(player.maxHp/12)}</b></div><div class="stat-line"><span>Mana</span><b>${player.maxMp}</b></div><div class="stat-line"><span>Gold</span><b>${player.gold}</b></div><div class="stat-line"><span>Zone</span><b>${player.zone}</b></div></section></div>`;
 else if(tab==='skills')html=`<div class="skill-list">${a.skills.map((s,i)=>`<article class="sys-card"><span class="skill-key">${['Q','E','R'][i]}</span><div><h3>${escapeHTML(s.name)}</h3><p>${escapeHTML(s.desc||`${s.kind} ability`)}</p><small>${s.mana} MP · ${s.cd}s cooldown · ${s.kind.toUpperCase()}</small></div></article>`).join('')}<section class="sys-card"><h3>EVOLUTION</h3>${(a.evolution||[]).map(e=>`<p>LV ${e.level} · ${escapeHTML(e.name)} — ${escapeHTML(e.desc)}</p>`).join('')||'<p>Your authority has no recorded evolution.</p>'}</section></div>`;
 else if(tab==='inventory')html=`<div class="sys-card inventory-head"><h3>FIELD INVENTORY</h3><p>Consumables replenish between expeditions. Find relics in monster drops.</p><div class="inventory-grid"><button data-action="potion">${consumableIcon?.('potion')||'✚'} Healing tonic <b>×${player.potions}</b></button><button data-action="mana-potion">◈ Mana elixir <b>×${player.elixirs}</b></button>${player.inventory.map((it,i)=>`<button data-item="${i}">${escapeHTML(it.name)} <b>${escapeHTML(it.rarity)}</b></button>`).join('')}</div></div>`;
 else if(tab==='equipment')html=`<div class="equipment-grid"><section class="sys-card"><h3>WEAPON · ${data.path.toUpperCase()}</h3>${weaponIcon?.(data.path)||'⚔'}<p>Attack ${player.atk} · Reach ${player.range}</p></section><section class="sys-card"><h3>ARMOR</h3>${armorIcon?.('armor')||'▣'}<p>${player.equipment[0]?.name||'Wanderer’s cloak'}</p><p>Defense ${Math.round((player.mods.defPct||0)*100)}%</p></section></div>`;
 else if(tab==='quest')html=`<section class="sys-card"><h3>${escapeHTML($('#quest-name').textContent)}</h3><p>${escapeHTML($('#quest-objective').textContent)}</p><p>Creatures slain: ${player.kills} · Bosses: ${player.bossKills}</p><button data-action="track">TRACK QUEST</button></section>`;
 else if(tab==='dungeon')html=`<div class="dungeon-grid"><section class="sys-card"><h3>RIFTS OF THE ECLIPSE</h3><p>Dangerous portals lead to shifting battlefields. Every third depth is ruled by a boss.</p><div class="dungeon-options"><button data-zone="forest">WHISPERING WOOD <small>Recommended Lv ${Math.max(1,depth)}</small></button><button data-zone="dungeon">SUNKEN RELIQUARY <small>Depth ${depth}</small></button><button data-zone="lava">ASHEN CALDERA <small>High risk · high reward</small></button><button data-action="return-village">RETURN TO HOLLOWMERE</button></div></section></div>`;
 else if(tab==='bestiary')html=`<div class="bestiary-grid">${[...monsterTypes,'boss_grove','boss_wyrm','boss_hollow'].map(t=>`<div class="sys-card bestiary-entry"><canvas width="64" height="64" data-monster="${t}"></canvas><b>${t.replace('boss_','').replaceAll('_',' ').toUpperCase()}</b><small>${player.kills?`Sighted · ${Math.max(1,Math.floor(player.kills/monsterTypes.length))} defeated`:'Unknown creature'}</small></div>`).join('')}</div>`;
 else if(tab==='achievements')html=`<div class="achievement-grid">${[['First Blood',player.kills>0,'Defeat your first creature.'],['Awakened',true,'Receive your unique authority.'],['Rift Walker',player.quests>0,'Clear a rift.'],['Giant Slayer',player.bossKills>0,'Defeat a boss.'],['Ascendant',player.level>=5,'Reach level five.'],['Collector',player.inventory.length>=3,'Gather three relics.']].map(([n,ok,d])=>`<div class="sys-card ${ok?'unlocked':''}"><b>${ok?'★':'☆'} ${n}</b><p>${d}</p></div>`).join('')}</div>`;
 else if(tab==='map')html=`<section class="sys-card map-card"><h3>KNOWN LANDS</h3><div class="map-zones">${mapZones.map(z=>`<button data-zone="${z.type}" class="${z.type===mapType?'current':''}"><b>${z.name}</b><small>${z.weather} · ${z.type===mapType?'CURRENT LOCATION':'EXPLORE'}</small></button>`).join('')}</div></section>`;
 else if(tab==='settings')html=`<section class="sys-card"><h3>SYSTEM SETTINGS</h3><p>Progress is saved automatically on this device.</p><button data-action="save">SAVE NOW</button><button data-action="title">RETURN TO TITLE</button><p>Move: WASD / arrows · Attack: click / space · Skills: Q E R · Dodge: shift · System: Tab</p></section>`;
 c.innerHTML=html;c.querySelectorAll('canvas[data-monster]').forEach(el=>{const frame=getMonsterFrame(el.dataset.monster,0);if(frame)el.getContext('2d').drawImage(frame,0,0,64,64)});
}

