// ---------------------------- gameplay ----------------------------
const relics=[{name:'Moon-Split Fang',rarity:'Rare',atk:4},{name:'Ashen Heart',rarity:'Epic',atk:7},{name:'Crown of Quiet Stars',rarity:'Legendary',atk:11},{name:'Warden’s Thread',rarity:'Uncommon',atk:3}];
let attackHeld=false,heavyHeld=false,interactTarget=null,saveAccumulator=0;
function nearestEnemy(range=500){return monsters.filter(m=>m.hp>0).sort((a,b)=>dist(player.x,player.y,a.x,a.y)-dist(player.x,player.y,b.x,b.y)).find(m=>dist(player.x,player.y,m.x,m.y)<range)}
function damageMonster(m,amount,opts={}){if(!m||m.hp<=0)return;const crit=Math.random()<(player.mods.crit||0),dmg=Math.max(1,Math.round(amount*(crit?1.75:1)*(m.marked>0?1.25:1)*(m.burn>0?1+(player.mods.execute||0):1)));m.hp-=dmg;m.aggro=true;m.stun=Math.max(m.stun,opts.stun||0);m.slow=Math.max(m.slow,opts.slow||0);m.burn=Math.max(m.burn,opts.burn||0);if(opts.knockback){const a=Math.atan2(m.y-player.y,m.x-player.x);m.x+=Math.cos(a)*opts.knockback;m.y+=Math.sin(a)*opts.knockback}effects.push({x:m.x,y:m.y,radius:crit?22:12,life:.22,max:.22,color:crit?'#ffe17b':(opts.color||'#fff'),width:2});if(player.mods.lifesteal)player.hp=Math.min(player.maxHp,player.hp+dmg*player.mods.lifesteal);if(m.hp<=0)killMonster(m)}
function killMonster(m){m.hp=0;player.kills++;player.xp+=m.boss?100:18+depth*2;player.gold+=m.loot||8;player.combo++;comboTimer=4;if(player.mods.killHeal)player.hp=Math.min(player.maxHp,player.hp+player.maxHp*player.mods.killHeal);if(Math.random()<(m.boss?.95:.2))drops.push({x:m.x,y:m.y,bob:rand(0,6),type:'relic',color:m.boss?'#ffcf6e':'#8de6d1',item:structuredClone(pick(relics))});if(m.boss){player.bossKills++;toast('BOSS DEFEATED · A relic has fallen');$('#quest-objective').textContent='The guardian is defeated. Find the return gate or press Tab to travel.'}gainLevels();}
function gainLevels(){while(player.xp>=player.nextXp){player.xp-=player.nextXp;player.level++;player.nextXp=Math.floor(player.nextXp*1.35);player.maxHp+=16;player.maxMp+=7;player.atk+=2;player.hp=player.maxHp;player.mp=player.maxMp;toast(`LEVEL UP · ${player.level}`);for(const e of player.ability.evolution||[])if(e.level===player.level){applyMods(e.mods);toast(`EVOLUTION · ${e.name}`)}}updateHUD()}
function hitEnemies(x,y,r,damage,opts={}){for(const m of monsters)if(m.hp>0&&dist(x,y,m.x,m.y)<r+m.radius)damageMonster(m,damage,{...opts,color:opts.color||'#d8eaff'})}
function attack(heavy=false){if(!player||paused||player.hp<=0)return;const target=nearestEnemy(player.range+150);let a=mouse.down?Math.atan2(mouse.y-H/2,mouse.x-W/2):(target?Math.atan2(target.y-player.y,target.x-player.x):player.dir);player.dir=a;const cost=heavy?24:0;if(heavy&&player.stamina<cost){toast('Not enough stamina');return}if(heavy)player.stamina-=cost;const rate=(heavy?.72:.38)/(1+(player.mods.atkSpeed||0));if(time-lastAttack<rate)return;lastAttack=time;player.attack=heavy?.34:.22;const damage=player.atk*(1+(player.mods.atkPct||0))*(heavy?2.15:1);if(data.path==='bow'||data.path==='staff'){const speed=data.path==='bow'?520:410;projectiles.push({x:player.x+Math.cos(a)*18,y:player.y+Math.sin(a)*18,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,radius:data.path==='bow'?5:8,life:player.range/speed,color:data.path==='bow'?'#f4d18c':'#a9a0ff',dmg:damage,pierce:0,owner:'player',burn:player.mods.burn||0})}else{const reach=heavy?player.range*1.55:player.range+10;for(const m of monsters)if(m.hp>0&&dist(player.x,player.y,m.x,m.y)<reach+m.radius&&Math.abs(Math.atan2(Math.sin(Math.atan2(m.y-player.y,m.x-player.x)-a),Math.cos(Math.atan2(m.y-player.y,m.x-player.x)-a)))<.9)damageMonster(m,damage,{stun:heavy?.45:0,burn:player.mods.burn?2:0,slow:player.mods.slowOnHit?2:0,knockback:heavy?55:0})}effects.push({x:player.x+Math.cos(a)*35,y:player.y+Math.sin(a)*25,radius:heavy?42:25,life:.18,max:.18,color:heavy?'#ffd27a':'#dcecff',width:2})}
function castSkill(i){if(!player||paused)return;const s=player.ability.skills[i];if(!s||player.cd[i]>0)return;const cost=s.mana||0;if(player.mp<cost){toast('Insufficient mana');return}player.mp-=cost;player.cd[i]=(s.cd||6)*Math.max(.35,1-(player.mods.cdr||0));const color=s.color||player.ability.color||'#a9d8ff',aim=mouse.down?Math.atan2(mouse.y-H/2,mouse.x-W/2):(nearestEnemy(500)?Math.atan2(nearestEnemy(500).y-player.y,nearestEnemy(500).x-player.x):player.dir),range=s.range||280,radius=(s.radius||70)*(1+(player.mods.radiusPct||0));player.dir=aim;
 if(s.kind==='projectile'||s.kind==='drain'){const sp=s.speed||380;projectiles.push({x:player.x+Math.cos(aim)*16,y:player.y+Math.sin(aim)*16,vx:Math.cos(aim)*sp,vy:Math.sin(aim)*sp,radius:s.width?Math.max(6,s.width/2):(s.radius||9),life:(s.range||range)/sp,color,dmg:player.atk*(s.dmg||2),pierce:Math.max(0,(s.pierce||1)-1),owner:'player',burn:s.burn||0,slow:s.slow||0,lifeSteal:s.lifeSteal||0})}
 else if(s.kind==='beam'||s.kind==='chain'){const list=monsters.filter(m=>m.hp>0&&dist(player.x,player.y,m.x,m.y)<range).sort((a,b)=>dist(player.x,player.y,a.x,a.y)-dist(player.x,player.y,b.x,b.y)),count=s.kind==='chain'?(s.count||5)+(player.mods.chainBonus||0):10;let prev={x:player.x,y:player.y};for(const m of list.slice(0,count)){if(s.kind==='beam'&&Math.abs(Math.atan2(Math.sin(Math.atan2(m.y-player.y,m.x-player.x)-aim),Math.cos(Math.atan2(m.y-player.y,m.x-player.x)-aim)))>.18)continue;effects.push({x:(prev.x+m.x)/2,y:(prev.y+m.y)/2,radius:dist(prev.x,prev.y,m.x,m.y)/2,life:.26,max:.26,color,width:4});damageMonster(m,player.atk*(s.dmg||2),{color,slow:s.slow||0});prev=m}}
 else if(['nova','drainzone','healzone','pull'].includes(s.kind)){hitEnemies(player.x,player.y,radius,player.atk*(s.dmg||1),{color,slow:s.slow||0,stun:s.freeze?1:0});if(s.kind==='pull')for(const m of monsters)if(m.hp>0&&dist(player.x,player.y,m.x,m.y)<radius){const a=Math.atan2(player.y-m.y,player.x-m.x);m.x+=Math.cos(a)*35;m.y+=Math.sin(a)*35}if(s.kind==='healzone')player.hp=Math.min(player.maxHp,player.hp+player.maxHp*(s.healPerSec||.1)*(s.duration||3));if(s.kind==='drainzone')player.hp=Math.min(player.maxHp,player.hp+player.maxHp*(s.lifeSteal||.08));effects.push({x:player.x,y:player.y,radius,life:.65,max:.65,color,width:4})}
 else if(s.kind==='heal'){player.hp=Math.min(player.maxHp,player.hp+player.maxHp*(s.healPct||.3));effects.push({x:player.x,y:player.y,radius:40,life:.8,max:.8,color,fill:true})}
 else if(s.kind==='buff'||s.kind==='mark'){if(s.mods)applyMods(s.mods);if(s.kind==='mark')for(const m of monsters)if(dist(player.x,player.y,m.x,m.y)<radius)m.marked=s.duration||6;if(s.shieldPct)player.shield=Math.max(player.shield,player.maxHp*s.shieldPct);if(s.kind==='buff'&&s.duration)player.buffs.push({mods:s.mods||{},time:s.duration});if(s.duration&&s.kind==='mark')player.buffs.push({time:s.duration,mods:s.mods||{},revert:true});effects.push({x:player.x,y:player.y,radius:48,life:.7,max:.7,color,fill:true})}
 else if(s.kind==='shield'){player.shield=Math.max(player.shield,player.maxHp*(s.shieldPct||.2));player.buffs.push({mods:s.mods||{},time:s.duration||6});effects.push({x:player.x,y:player.y,radius:45,life:.8,max:.8,color})}
 else if(['dash','teleport','blinkstrike'].includes(s.kind)){const old={x:player.x,y:player.y},d=s.kind==='dash'?(s.distance||170):Math.min(range,dist(player.x,player.y,mouse.x+camera.x-W/2,mouse.y+camera.y-H/2));if(s.kind==='blinkstrike'){const m=nearestEnemy(range);if(m){player.x=m.x+Math.cos(aim+Math.PI)*32;player.y=m.y+Math.sin(aim+Math.PI)*32;damageMonster(m,player.atk*(s.dmg||2),{color})}}else{player.x=clamp(player.x+Math.cos(aim)*d,20,mapW*TS-20);player.y=clamp(player.y+Math.sin(aim)*d,20,mapH*TS-20);if(s.dmg)hitEnemies(player.x,player.y,s.radius||34,player.atk*s.dmg,{color})}player.invuln=Math.max(player.invuln,s.iframes||.3);effects.push({x:old.x,y:old.y,radius:32,life:.35,max:.35,color})}
