 else if(s.kind==='summon'){player.buffs.push({time:s.duration||8,mods:{atkPct:.15}});const m=nearestEnemy(320);if(m)damageMonster(m,player.atk*(s.dmg||1),{color});effects.push({x:player.x,y:player.y,radius:52,life:.75,max:.75,color})}
